package io.github.miklires.mclans.util;import io.github.miklires.mclans.MClansPlugin;import org.bukkit.entity.Player;public final class PluginScheduler{private final MClansPlugin plugin;public PluginScheduler(MClansPlugin plugin){this.plugin=plugin;}public void global(Runnable task){plugin.getServer().getGlobalRegionScheduler().execute(plugin,task);}public void player(Player player,Runnable task){player.getScheduler().execute(plugin,task,null,1L);}}
